// components/pages/TillRegistration.js - Multi-step form with beautiful design
import React, { useState } from 'react';
import { apiCall, normalizePhone } from '../../utils/api';

const TillRegistration = ({ showToast }) => {
  const [currentStep, setCurrentStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    phone: '',
    name: '',
    idNumber: '',
    dob: '',
    tillNumber: '',
    storeNumber: '',
    operatorId: ''
  });
  const [fetchInfo, setFetchInfo] = useState({ type: '', message: '' });
  const [feedback, setFeedback] = useState('');

  const totalSteps = 4;

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleFetchLine = async () => {
    const phone = formData.phone.trim();
    if (!phone) {
      setFetchInfo({ type: 'error', message: 'Please enter a phone number' });
      return;
    }

    setFetchInfo({ type: 'info', message: 'Searching for customer...' });
    setLoading(true);

    const res = await apiCall('getLines');
    if (!res.success || !res.lines) {
      setFetchInfo({ type: 'error', message: 'Error fetching customer data' });
      setLoading(false);
      return;
    }

    const normalizedInput = normalizePhone(phone);
    const found = res.lines.find(line => normalizePhone(line.phone) === normalizedInput);

    if (found) {
      setFormData(prev => ({
        ...prev,
        name: found.name,
        idNumber: found.idNumber,
        dob: found.dob,
        operatorId: generateOperatorId(found.name)
      }));
      setFetchInfo({ type: 'success', message: `✓ Customer found: ${found.name}` });
      showToast('Customer found! Proceed to next step.');
      // Auto-advance to next step after successful fetch
      setTimeout(() => {
        setCurrentStep(2);
      }, 500);
    } else {
      setFetchInfo({ type: 'error', message: `No customer found with phone number "${phone}"` });
      showToast('Customer not found. Please register the line first.', true);
    }
    setLoading(false);
  };

  const generateOperatorId = (name) => {
    const nameParts = name.trim().split(/\s+/);
    if (nameParts.length === 1) {
      return nameParts[0].substring(0, 2).toUpperCase();
    }
    return (nameParts[0].charAt(0) + nameParts[nameParts.length - 1].charAt(0)).toUpperCase();
  };

  const handleNext = () => {
    if (currentStep === 1 && !formData.name) {
      setFetchInfo({ type: 'error', message: 'Please search for a customer first' });
      return;
    }
    if (currentStep < totalSteps) {
      setCurrentStep(currentStep + 1);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handlePrevious = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleSubmit = async () => {
    const { phone, name, tillNumber, storeNumber, operatorId } = formData;

    if (!phone || !tillNumber || !storeNumber || !name) {
      setFeedback({ type: 'error', message: 'Please fill in all required fields' });
      return;
    }

    setLoading(true);
    setFeedback({ type: 'info', message: 'Registering till...' });

    const cleanPhone = phone.replace(/\D/g, '');
    const res = await apiCall('registerTill', { 
      ...formData,
      phone: cleanPhone
    });

    if (res.success) {
      setFeedback({ type: 'success', message: '✅ Till registered successfully!' });
      showToast('Till registered successfully!');
      // Reset form after 2 seconds
      setTimeout(() => {
        setFormData({
          phone: '',
          name: '',
          idNumber: '',
          dob: '',
          tillNumber: '',
          storeNumber: '',
          operatorId: ''
        });
        setCurrentStep(1);
        setFeedback('');
        setFetchInfo({ type: '', message: '' });
      }, 2000);
    } else {
      setFeedback({ type: 'error', message: res.error || 'Registration failed. Please try again.' });
    }
    setLoading(false);
  };

  const renderStepIndicator = () => {
    const steps = ['Customer Lookup', 'Customer Details', 'Till Details', 'Review & Register'];
    return (
      <div className="step-indicator">
        {steps.map((step, index) => (
          <div key={index} className={`step-item ${index + 1 === currentStep ? 'active' : ''} ${index + 1 < currentStep ? 'completed' : ''}`}>
            <div className="step-circle">
              {index + 1 < currentStep ? <i className="fas fa-check"></i> : index + 1}
            </div>
            <div className="step-label">{step}</div>
            {index < steps.length - 1 && <div className="step-line"></div>}
          </div>
        ))}
      </div>
    );
  };

  const renderStep1 = () => (
    <div className="step-content">
      <div className="step-header">
        <h3><i className="fas fa-search"></i> Find Customer</h3>
        <p>Enter the customer's phone number to look up their details</p>
      </div>
      <div className="form-group">
        <label><i className="fas fa-phone"></i> Phone Number</label>
        <div className="input-group">
          <input 
            type="tel" 
            name="phone"
            value={formData.phone}
            onChange={handleChange}
            placeholder="0712345678"
            className="input-large"
          />
          <button 
            type="button" 
            className="btn-search" 
            onClick={handleFetchLine}
            disabled={loading}
          >
            <i className={`fas ${loading ? 'fa-spinner fa-pulse' : 'fa-search'}`}></i>
            {loading ? 'Searching...' : 'Search'}
          </button>
        </div>
        {fetchInfo.message && (
          <div className={`fetch-info ${fetchInfo.type}`}>
            <i className={`fas ${fetchInfo.type === 'success' ? 'fa-check-circle' : fetchInfo.type === 'error' ? 'fa-exclamation-circle' : 'fa-info-circle'}`}></i>
            {fetchInfo.message}
          </div>
        )}
      </div>
      {formData.name && (
        <div className="customer-preview">
          <div className="preview-card">
            <i className="fas fa-user-circle"></i>
            <div>
              <h4>{formData.name}</h4>
              <p><i className="fas fa-id-card"></i> {formData.idNumber}</p>
              <p><i className="fas fa-phone"></i> {formData.phone}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  const renderStep2 = () => (
    <div className="step-content">
      <div className="step-header">
        <h3><i className="fas fa-user-check"></i> Customer Details</h3>
        <p>Review and confirm customer information</p>
      </div>
      <div className="form-row">
        <div className="form-group">
          <label><i className="fas fa-user"></i> Full Name</label>
          <input 
            type="text" 
            name="name"
            value={formData.name}
            readOnly
            className="input-readonly"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-id-card"></i> ID Number</label>
          <input 
            type="text" 
            name="idNumber"
            value={formData.idNumber}
            readOnly
            className="input-readonly"
          />
        </div>
      </div>
      <div className="form-row">
        <div className="form-group">
          <label><i className="fas fa-calendar"></i> Date of Birth</label>
          <input 
            type="text" 
            name="dob"
            value={formData.dob}
            readOnly
            className="input-readonly"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-phone"></i> Phone Number</label>
          <input 
            type="text" 
            name="phone"
            value={formData.phone}
            readOnly
            className="input-readonly"
          />
        </div>
      </div>
      <div className="form-group">
        <label><i className="fas fa-user-tag"></i> Operator ID</label>
        <input 
          type="text" 
          name="operatorId"
          value={formData.operatorId}
          readOnly
          className="input-readonly"
        />
        <small className="helper-text">Auto-generated from customer name</small>
      </div>
    </div>
  );

  const renderStep3 = () => (
    <div className="step-content">
      <div className="step-header">
        <h3><i className="fas fa-cash-register"></i> Till Information</h3>
        <p>Enter the till and store details</p>
      </div>
      <div className="form-row">
        <div className="form-group">
          <label><i className="fas fa-hashtag"></i> Till Number <span className="required">*</span></label>
          <input 
            type="text" 
            name="tillNumber"
            value={formData.tillNumber}
            onChange={handleChange}
            placeholder="e.g., T001"
            className="input-large"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-store"></i> Store Number <span className="required">*</span></label>
          <input 
            type="text" 
            name="storeNumber"
            value={formData.storeNumber}
            onChange={handleChange}
            placeholder="e.g., STR01"
            className="input-large"
          />
        </div>
      </div>
      <div className="info-box">
        <i className="fas fa-info-circle"></i>
        <span>Ensure the till number is unique and store number is correct</span>
      </div>
    </div>
  );

  const renderStep4 = () => (
    <div className="step-content">
      <div className="step-header">
        <h3><i className="fas fa-clipboard-check"></i> Review & Register</h3>
        <p>Please review all details before submitting</p>
      </div>
      <div className="review-card">
        <div className="review-section">
          <h4><i className="fas fa-user"></i> Customer Information</h4>
          <div className="review-row">
            <span className="review-label">Full Name</span>
            <span className="review-value">{formData.name}</span>
          </div>
          <div className="review-row">
            <span className="review-label">ID Number</span>
            <span className="review-value">{formData.idNumber}</span>
          </div>
          <div className="review-row">
            <span className="review-label">Phone Number</span>
            <span className="review-value">{formData.phone}</span>
          </div>
          <div className="review-row">
            <span className="review-label">Date of Birth</span>
            <span className="review-value">{formData.dob}</span>
          </div>
          <div className="review-row">
            <span className="review-label">Operator ID</span>
            <span className="review-value">{formData.operatorId}</span>
          </div>
        </div>
        <div className="review-divider"></div>
        <div className="review-section">
          <h4><i className="fas fa-cash-register"></i> Till Details</h4>
          <div className="review-row">
            <span className="review-label">Till Number</span>
            <span className="review-value highlight">{formData.tillNumber}</span>
          </div>
          <div className="review-row">
            <span className="review-label">Store Number</span>
            <span className="review-value highlight">{formData.storeNumber}</span>
          </div>
        </div>
      </div>
      {feedback && (
        <div className={`fetch-info ${feedback.type}`} style={{ marginTop: '1rem' }}>
          {feedback.message}
        </div>
      )}
    </div>
  );

  const renderStep = () => {
    switch(currentStep) {
      case 1: return renderStep1();
      case 2: return renderStep2();
      case 3: return renderStep3();
      case 4: return renderStep4();
      default: return null;
    }
  };

  return (
    <div className="form-container multi-step-form">
      <h3 className="section-title">
        <i className="fas fa-cash-register"></i> Register New Till
        <span className="step-counter">Step {currentStep} of {totalSteps}</span>
      </h3>
      
      {renderStepIndicator()}
      
      <div className="step-content-wrapper">
        {renderStep()}
      </div>

      <div className="step-actions">
        {currentStep > 1 && (
          <button 
            type="button" 
            className="btn-secondary" 
            onClick={handlePrevious}
            disabled={loading}
          >
            <i className="fas fa-arrow-left"></i> Previous
          </button>
        )}
        {currentStep < totalSteps ? (
          <button 
            type="button" 
            className="btn" 
            onClick={handleNext}
            disabled={loading || !formData.name}
          >
            Next <i className="fas fa-arrow-right"></i>
          </button>
        ) : (
          <button 
            type="button" 
            className="btn btn-success" 
            onClick={handleSubmit}
            disabled={loading}
          >
            <i className={`fas ${loading ? 'fa-spinner fa-pulse' : 'fa-save'}`}></i>
            {loading ? 'Registering...' : 'Register Till'}
          </button>
        )}
      </div>
    </div>
  );
};

export default TillRegistration;
